/*
  03 - Normalize KEV Catalog

  Objetivo:
  - Recibir el JSON de CISA KEV aunque venga como string en item.json.data.
  - Parsearlo si hace falta.
  - Extraer vulnerabilities[].
  - Convertir cada vulnerabilidad KEV en un documento plano.
  - Normalizar cveID → cve_id.
*/

const input = items[0]?.json || {};

let kevRoot = null;

// Caso 1: el catálogo ya viene como JSON directo
if (input.vulnerabilities) {
  kevRoot = input;
}

// Caso 2: el catálogo viene dentro de input.data como string JSON
else if (typeof input.data === "string") {
  try {
    kevRoot = JSON.parse(input.data);
  } catch (error) {
    return [
      {
        json: {
          error: true,
          message: "No se pudo parsear input.data como JSON.",
          details: error.message,
          received_keys: Object.keys(input),
          sample: input.data.slice(0, 500)
        }
      }
    ];
  }
}

// Caso 3: el catálogo viene dentro de input.body como string JSON
else if (typeof input.body === "string") {
  try {
    kevRoot = JSON.parse(input.body);
  } catch (error) {
    return [
      {
        json: {
          error: true,
          message: "No se pudo parsear input.body como JSON.",
          details: error.message,
          received_keys: Object.keys(input),
          sample: input.body.slice(0, 500)
        }
      }
    ];
  }
}

// Caso 4: viene dentro de input.data como objeto
else if (input.data?.vulnerabilities) {
  kevRoot = input.data;
}

// Caso 5: viene dentro de input.body como objeto
else if (input.body?.vulnerabilities) {
  kevRoot = input.body;
}

if (!kevRoot || !Array.isArray(kevRoot.vulnerabilities)) {
  return [
    {
      json: {
        error: true,
        message: "No se encontró el array vulnerabilities en la respuesta de KEV.",
        received_keys: Object.keys(input),
        received_sample: input
      }
    }
  ];
}

const vulnerabilities = kevRoot.vulnerabilities;

return vulnerabilities
  .filter(vuln => vuln.cveID)
  .map(vuln => {
    const cveId = String(vuln.cveID || "").trim().toUpperCase();

    return {
      json: {
        cve_id: cveId,
        kev_flag: true,
        kev_score: 1,

        vendor_project: vuln.vendorProject || null,
        product: vuln.product || null,
        vulnerability_name: vuln.vulnerabilityName || null,
        short_description: vuln.shortDescription || null,
        date_added: vuln.dateAdded || null,
        due_date: vuln.dueDate || null,
        known_ransomware: vuln.knownRansomwareCampaignUse || null,
        required_action: vuln.requiredAction || null,
        notes: vuln.notes || null,
        cwes: vuln.cwes || [],

        catalog_title: kevRoot.title || "CISA Known Exploited Vulnerabilities Catalog",
        catalog_version: kevRoot.catalogVersion || null,
        catalog_date_released: kevRoot.dateReleased || null,
        catalog_count: kevRoot.count || vulnerabilities.length,

        source: "CISA KEV GitHub",
        source_url: "https://raw.githubusercontent.com/cisagov/kev-data/develop/known_exploited_vulnerabilities.json",

        pipeline_stage: "kev_catalog_normalized",
        updated_at: new Date().toISOString()
      }
    };
  });
